// th14_s3_w09: TH14 v1.00b st03.ecl.txt::MainSub06b (721-748) + closure.
// Source frame 0 = first MainSub06b frame, card frame 0 = phase start; OPENING_BUFFER 120.
const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// TH14 synthetic bullet aliases (source type 8 -> TH14_RICE, 5 -> TH14_BALL2).
const TH14_RICE: int = 480;
const TH14_BALL2: int = 432;

const GIRL_HP: int = 260;      // enmCreate("GirlC01", ..., 260, 1000, 1)
const PHANTOM_HP: int = 130;   // enmCreate("Phantom01", ..., 130, 1000, 1)

// GirlC01 EX: ANIM(a=1) + WAIT(60) + ACCEL(a=60, r=0.025, s=current angle).
// Birth ANIM/SPEEDUP presentation is omitted per policy; its -4*speed retreat is
// folded into the fire position below. The standalone WAIT(60) is kept.
xformdef GIRL_ACCEL {
    wait(60);
    set_gravity(at_effect(0.025fx * cos($self_angle)),
                at_effect(0.025fx * sin($self_angle)));
    wait(60);
    set_gravity(0fx, 0fx);
}

// st03 GirlC01_at (258-293). %A starts at pi/2 and adds %F0 per shot; the closure
// and entry snapshot give no writer for F0 (fresh enemy slots are 0), so the stream
// stays at 90 deg. etAim(3) x etCount(1,1) is one fixed-direction bullet per shot.
// etDist 16 combined with the ANIM retreat (-4*0.5) gives +14 px along the shot angle.
async sub girl_fire() {
    var dir: angle = 90deg;
    var gap: int = 10;                       // Lunatic wait([-1])
    if global(GVAR_RANK) == RANK_EASY { gap = 40; }
    if global(GVAR_RANK) == RANK_NORMAL { gap = 20; }
    if global(GVAR_RANK) == RANK_HARD { gap = 15; }
    wait(60);
    for i in 0..50 {                        // $B = 50
        _ = fire(TH14_RICE, 4,
                 $self_x + 14fx * cos(dir),
                 $self_y + 14fx * sin(dir),
                 0.5fx, dir, GIRL_ACCEL, none);
        wait(gap);
    }
}

// st03 GirlC01 (236-256). enmCreateM children are mirrored: their ordinary moveVel
// angles are reflected (side 1 uses pi - angle). Firing angles are not mirrored.
async sub girl_main(side: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                      // setHurtbox(24,24) -> 24*0.5
    set_hitbox(8fx);                        // setHitbox(16,16) -> 16*0.5
    var dir0: angle = -45deg;               // moveVel(-0.7853982, 1.5)
    var dir1: angle = 0deg;                 // moveVelTime(80, 1, 0, 1.5)
    if side == 1 {
        dir0 = -135deg;
        dir1 = 180deg;
    }
    move_vel(0, dir0, 1.5fx, EASE_LINEAR);
    move_vel(80, dir1, 1.5fx, EASE_QUAD_IN);  // source mode 1 = t^2
    spawn girl_fire();
    wait(120);
    loop { wait(1000); }
}

// st03 Phantom01_at (859-880). etAim(0) x etCount(1,1): one aimed bullet, speed 2.
// diffWait arguments are evaluated in E/N/H/L order in the source expression; all
// four RAND reads are kept, only the selected rank's value is used.
async sub phantom_fire() {
    var rank: int = global(GVAR_RANK);
    var w_e: int = 60 + rand(180);
    var w_n: int = 60 + rand(40);
    var w_h: int = 60 + rand(40);
    var w_l: int = 40 + rand(40);
    var w1: int = w_l;
    if rank == RANK_EASY { w1 = w_e; }
    if rank == RANK_NORMAL { w1 = w_n; }
    if rank == RANK_HARD { w1 = w_h; }
    wait(w1);
    var a: angle = aim_player();
    // ANIM(a=1) retreat: -4*2.0 px along the shot angle, aim taken before it.
    _ = fire(TH14_BALL2, 6,
             $self_x - 8fx * cos(a),
             $self_y - 8fx * sin(a),
             2fx, a, none, none);

    var shots: int = 0;                     // diffI($A, 0, 1, 4, 8)
    if rank == RANK_NORMAL { shots = 1; }
    if rank == RANK_HARD { shots = 4; }
    if rank == RANK_LUNATIC { shots = 8; }
    for i in 0..shots {
        var d_e: int = 30 + rand(40);
        var d_n: int = 30 + rand(40);
        var d_h: int = 60 + rand(20);
        var d_l: int = 60 + rand(20);
        var d: int = d_l;
        if rank == RANK_EASY { d = d_e; }
        if rank == RANK_NORMAL { d = d_n; }
        if rank == RANK_HARD { d = d_h; }
        wait(d);
        a = aim_player();
        _ = fire(TH14_BALL2, 6,
                 $self_x - 8fx * cos(a),
                 $self_y - 8fx * sin(a),
                 2fx, a, none, none);
    }
    // Phantom01_at2 (source death callback, NHL) is unreachable under the approved
    // invincible, no-DPS shell; not synthesized as a timed burst.
}

// st03 Phantom01 (832-857). ABS layer: moveVel(0, 1) mirrored per side.
// REL layer: moveCircleRel(RANDRAD, 1deg/frame, 0, 0) then
// moveCircleRelTime(80, 0, retain omega, 16, 0) -> radius 0..16 linear.
// REL center is the layer position at setup (0), so the wobble rides on the drift.
async sub phantom_main(side: int) {
    set_invuln(65535);
    set_hurtbox(14fx);                      // setHurtbox(28,28) -> 28*0.5
    set_hitbox(8fx);                        // setHitbox(16,16) -> 16*0.5
    if global(GVAR_RANK) >= RANK_HARD {
        spawn phantom_fire();               // source !HL async
    }
    var stepx: fx = 1fx;
    if side == 1 { stepx = -1fx; }
    var theta: angle = (rand(65536) - 32768) as angle;  // RANDRAD -pi..pi
    var x: fx = $self_x;
    var y: fx = $self_y;
    var r: fx = 0fx;
    var tick: int = 0;
    loop {
        tick = tick + 1;
        if tick <= 80 {
            r = 16fx * (tick as fx) / 80fx;
        } else {
            r = 16fx;
        }
        theta = theta + 1deg;
        x = x + stepx;
        move_to(0, x + r * cos(theta), y + r * sin(theta), EASE_LINEAR);
        wait(1);
    }
}

// st03 MainSub07b / MainSub07c: 10 Phantoms every 40 frames per side.
async sub phantom_wave(side: int, delay0: int) {
    wait(delay0);                            // MainSub07c waits 20
    for i in 0..10 {
        var px: fx = -192fx;
        if side == 1 { px = 192fx; }
        var py: fx = 64fx + (rand(65536) as fx) / 65536 * 128fx;
        _ = spawn_enemy(px, py, PHANTOM_HP, 0, 1000, 0, phantom_main(side));
        wait(40);
    }
}

// st03 MainSub06b girl schedule: 3 left, 3 right, 3 left, one every 60 frames.
sub girl_waves() {
    for k1 in 0..3 {
        _ = spawn_enemy(-224fx, 160fx, GIRL_HP, 0, 1000, 0, girl_main(0));
        wait(60);
    }
    for k2 in 0..3 {
        _ = spawn_enemy(224fx, 160fx, GIRL_HP, 0, 1000, 0, girl_main(1));
        wait(60);
    }
    for k3 in 0..3 {
        _ = spawn_enemy(-224fx, 160fx, GIRL_HP, 0, 1000, 0, girl_main(0));
        wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn phantom_wave(0, 0);
    spawn phantom_wave(1, 20);
    girl_waves();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
